CLASS zcl_str_template DEFINITION PUBLIC FINAL CREATE PUBLIC.
  PUBLIC SECTION.
    METHODS format_flight_info
      IMPORTING
        is_flight TYPE sflights
      RETURNING
        VALUE(rv_formatted_string) TYPE string.
ENDCLASS.

CLASS zcl_str_template IMPLEMENTATION.
  METHOD format_flight_info.
    rv_formatted_string = |
      Fluggesellschaft: { is_flight-carrid }
      Flugnummer:     { is_flight-connid }
      Abflugort:      { is_flight-cityfrom }
      Zielort:        { is_flight-cityto }
      Flugdatum:      { is_flight-fldate DATE = USER }
      Freie Plätze:   { is_flight-seatsmax - is_flight-seatsocc }
    |.
  ENDMETHOD.
ENDCLASS.

CLASS zcl_demo_output_chain DEFINITION PUBLIC FINAL CREATE PUBLIC.
  PUBLIC SECTION.
    METHODS display_chained_output.
ENDCLASS.

CLASS zcl_demo_output_chain IMPLEMENTATION.
  METHOD display_chained_output.
    cl_demo_output=>begin_section( 'Chained Output Example'
    )->text( 'This is the first line.'
    )->text( 'This is the second line.'
    )->line(
    )->text( 'This is after the line.'
    )->end_section( ).
  ENDMETHOD.
ENDCLASS.

