CLASS ltcl_test DEFINITION FOR TESTING RISK LEVEL HARMLESS DURATION SHORT.
  PRIVATE SECTION.
    METHODS test_flight_builder FOR TESTING.
    METHODS test_flight_builder_optional FOR TESTING.
ENDCLASS.

CLASS ltcl_test IMPLEMENTATION.
  METHOD test_flight_builder.
    DATA(ls_flight) = NEW zcl_flight_builder( )->set_carrier( 'LH'
      )->set_connection( '400'
      )->set_date( '20251207'
      )->set_seats( iv_seatsocc = 80 iv_seatsmax = 100
      )->build_flight_config( ).

    cl_abap_unit_assert=>assert_equals( msg = 'Carrier sollte LH sein' act = ls_flight-carrid exp = 'LH' ).
    cl_abap_unit_assert=>assert_equals( msg = 'Status sollte AVAILABLE sein' act = ls_flight-status exp = 'AVAILABLE' ).
  ENDMETHOD.

  METHOD test_flight_builder_optional.
    DATA(ls_flight_full) = NEW zcl_flight_builder( )->set_carrier( 'AA'
      )->set_connection( '017'
      )->set_date( '20251208'
      )->set_seats( iv_seatsocc = 100 iv_seatsmax = 100
      )->build_flight_config( ).

    cl_abap_unit_assert=>assert_equals( msg = 'Status sollte FULL sein' act = ls_flight_full-status exp = 'FULL' ).

    DATA(ls_flight_overbooked) = NEW zcl_flight_builder( )->set_carrier( 'BA'
      )->set_connection( '249'
      )->set_date( '20251209'
      )->set_seats( iv_seatsocc = 101 iv_seatsmax = 100
      )->build_flight_config( ).

    cl_abap_unit_assert=>assert_equals( msg = 'Status sollte OVERBOOKED sein' act = ls_flight_overbooked-status exp = 'OVERBOOKED' ).
  ENDMETHOD.
ENDCLASS.
